import json, urllib.request, urllib.error, os, time

# Public GitHub token from env
token = os.environ.get('RORK_PUBLIC_GITHUB_TOKEN', '')
print(f"=== DIRECT GITHUB API ===")
print(f"token present: {bool(token)} (length {len(token)})")

if token:
    # GitHub HEAD SHA
    req = urllib.request.Request(
        "https://api.github.com/repos/ibb142/ivx-holdings-platform/branches/main",
        headers={"Authorization": f"token {token}", "Accept": "application/vnd.github.v3+json"}
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            data = json.loads(resp.read().decode('utf-8'))
        print(f"github_head_sha: {data['commit']['sha']}")
        print(f"github_head_message: {data['commit']['commit']['message'][:80]}")
        print(f"github_head_author: {data['commit']['commit']['author']['name']}")
        print(f"github_head_date: {data['commit']['commit']['committer']['date']}")
    except Exception as e:
        print(f"github_head: ERROR {e}")

    # Open PRs
    req2 = urllib.request.Request(
        "https://api.github.com/repos/ibb142/ivx-holdings-platform/pulls?state=open",
        headers={"Authorization": f"token {token}", "Accept": "application/vnd.github.v3+json"}
    )
    try:
        with urllib.request.urlopen(req2, timeout=15) as resp:
            prs = json.loads(resp.read().decode('utf-8'))
        print(f"open_prs_count: {len(prs)}")
        for pr in prs[:5]:
            print(f"  PR #{pr['number']}: {pr['title']} | head={pr['head']['sha'][:7]} | mergeable={pr.get('mergeable')} | state={pr.get('mergeable_state')}")
    except Exception as e:
        print(f"open_prs: ERROR {e}")
else:
    print("github: BLOCKED — no public GitHub token in environment")

# Direct Render API
print(f"\n=== DIRECT RENDER API ===")
render_key = os.environ.get('RENDER_API_KEY', '')
render_service = os.environ.get('RENDER_SERVICE_ID', '')
print(f"render_key present: {bool(render_key)} (length {len(render_key)})")
print(f"render_service_id: {render_service or 'NOT SET'}")

if render_key and render_service:
    # Service details
    req = urllib.request.Request(
        f"https://api.render.com/v1/services/{render_service}",
        headers={"Authorization": f"Bearer {render_key}", "Accept": "application/json"}
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            svc = json.loads(resp.read().decode('utf-8'))
        print(f"render_service_id: {svc.get('id')}")
        print(f"render_service_name: {svc.get('name')}")
        print(f"render_service_type: {svc.get('type')}")
        print(f"render_plan: {svc.get('plan')}")
        print(f"render_suspended: {svc.get('suspended')}")
        print(f"render_service_details: {svc.get('serviceDetails')}")
    except Exception as e:
        print(f"render_service: ERROR {e}")

    # Deploys
    req2 = urllib.request.Request(
        f"https://api.render.com/v1/services/{render_service}/deploys?limit=5",
        headers={"Authorization": f"Bearer {render_key}", "Accept": "application/json"}
    )
    try:
        with urllib.request.urlopen(req2, timeout=15) as resp:
            deploys = json.loads(resp.read().decode('utf-8'))
        if isinstance(deploys, list):
            print(f"render_recent_deploys: {len(deploys)}")
            for d in deploys[:5]:
                print(f"  deploy_id={d.get('id')} status={d.get('status')} commit={d.get('commit', {}).get('id', 'N/A')[:7]} created={d.get('createdAt')} finished={d.get('finishedAt')}")
        else:
            print(f"render_deploys: unexpected format: {deploys}")
    except Exception as e:
        print(f"render_deploys: ERROR {e}")
else:
    print("render: BLOCKED — private RENDER_API_KEY not available in sandbox")
